import java.time.*;

public class Solution {}

final class RenewalDate {
    static String calculate(String start, int months, int days) {
        LocalDate startDate = LocalDate.parse(start);
        Period period = Period.of(0, months, days);
        return startDate.plus(period).toString();
    }
}

